/**
 * Strict HTML sanitizer, URL validator, package-path guard, DOM-safe wikilink
 * renderer, and heading anchor extractor for PureKnowledge.
 *
 * Uses DOMParser in browser/DOM environments with a strict quote-aware
 * tokenizer fallback in non-DOM (Node) environments so every HTML string
 * reaching `dangerouslySetInnerHTML` is guaranteed safe.
 */
import { normalizeWikiLinkEscapes } from './knowledgeStore'

export interface SanitizeHtmlOptions {
  /**
   * Allow trusted YouTube nocookie iframes generated by `embedKnowledgeVideos`
   * inside `<figure data-video-source="...">`. Disabled by default.
   */
  allowTrustedVideoIframes?: boolean
  /**
   * Allow `data:image/svg+xml;base64,...` on `<img data-writer-asset-src="...">`
   * when produced from a verified local package asset and free of SVG active
   * content. Disabled by default.
   */
  allowLocalAssetSvgImg?: boolean
  /**
   * Allow `purescience-fs://` URLs ONLY on `<img>` elements carrying a verified
   * safe relative `data-writer-asset-src` (i.e. post-preparation images).
   * Disabled by default so raw Markdown/galleries can never smuggle shell FS URLs.
   */
  allowPreparedFsUrls?: boolean
}

export interface RenderedHeading {
  id: string
  text: string
  level: number
}

const STRIP_ELEMENTS = new Set([
  'script',
  'noscript',
  'template',
  'iframe',
  'object',
  'embed',
  'meta',
  'base',
  'link',
  'style',
  'form',
  'applet',
  'frame',
  'frameset',
  'portal',
  'math',
  'annotation-xml',
])

const STRIP_SVG_ELEMENTS = new Set([
  'script',
  'foreignobject',
  'animate',
  'animatetransform',
  'animatemotion',
  'animatecolor',
  'set',
  'handler',
  'discard',
  'mpath',
  'iframe',
  'object',
  'embed',
  'style',
  // Strip <title>/<desc> inside <svg> to eliminate HTML5 foreign-content mXSS.
  'title',
  'desc',
])

const URL_ATTRS = new Set([
  'href',
  'src',
  'xlink:href',
  'action',
  'formaction',
  'poster',
  'cite',
  'data',
])

const TRUSTED_VIDEO_IFRAME_SRC =
  /^https:\/\/www\.youtube-nocookie\.com\/embed\/[\w-]{11}$/
const TRUSTED_VIDEO_SOURCE_URL =
  /^https:\/\/www\.youtube\.com\/watch\?v=[\w-]{11}$/
const SAFE_RASTER_DATA_IMAGE =
  /^data:image\/(?:png|jpeg|jpg|gif|webp);base64,[A-Za-z0-9+/=\s]+$/i
const SAFE_SVG_DATA_IMAGE =
  /^data:image\/svg\+xml;base64,([A-Za-z0-9+/=\s]+)$/i

const ALLOWED_VIDEO_IFRAME_ATTRS = new Set([
  'src',
  'title',
  'style',
  'allow',
  'referrerpolicy',
  'allowfullscreen',
])

const ALLOWED_VIDEO_IFRAME_PERMISSIONS = new Set([
  'accelerometer',
  'autoplay',
  'clipboard-write',
  'encrypted-media',
  'gyroscope',
  'picture-in-picture',
  'fullscreen',
])

function decodeBasicEntities(value: string): string {
  return value
    .replace(/&#x([0-9a-f]+);?/gi, (_m, hex: string) => {
      const code = Number.parseInt(hex, 16)
      return Number.isFinite(code) && code >= 0 && code <= 0x10ffff
        ? String.fromCodePoint(code)
        : ''
    })
    .replace(/&#(\d+);?/g, (_m, dec: string) => {
      const code = Number.parseInt(dec, 10)
      return Number.isFinite(code) && code >= 0 && code <= 0x10ffff
        ? String.fromCodePoint(code)
        : ''
    })
    .replace(/&colon;/gi, ':')
    .replace(/&tab;/gi, '\t')
    .replace(/&newline;/gi, '\n')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
}

/**
 * Normalize CSS text by decoding HTML entities, stripping CSS comments, and
 * unescaping CSS backslash hex/character escapes before security checks.
 */
export function normalizeCssForSecurityCheck(value: string): string {
  let text = decodeBasicEntities(value)
  // Strip CSS comments (including unclosed trailing comment)
  text = text.replace(/\/\*[\s\S]*?(?:\*\/|$)/g, '')
  // Unescape CSS hex escapes (\6a, \000075 ) and single-char escapes (\u)
  text = text.replace(/\\([0-9a-f]{1,6})[\t\n\f\r ]?/gi, (_m, hex: string) => {
    const code = Number.parseInt(hex, 16)
    return Number.isFinite(code) && code > 0 && code <= 0x10ffff
      ? String.fromCodePoint(code)
      : ''
  })
  text = text.replace(/\\([^\r\n\f])/g, '$1')
  // Remove ASCII control characters
  return text.replace(/[\u0000-\u001f\u007f]+/g, '')
}

function normalizeForSchemeCheck(value: string): string {
  // Decode entities and remove ASCII control chars + whitespace that browsers
  // ignore when parsing URL schemes (e.g. "java\tscript:", "&#106;avascript:").
  return decodeBasicEntities(value)
    .replace(/[\u0000-\u0020\u007f]+/g, '')
    .toLowerCase()
}

function decodeBase64Utf8(base64: string): string | null {
  try {
    const clean = base64.replace(/\s+/g, '')
    if (!clean || clean.length % 4 === 1 || !/^[A-Za-z0-9+/=]+$/.test(clean)) {
      return null
    }
    if (typeof atob === 'function') {
      const raw = atob(clean)
      const bytes = new Uint8Array(raw.length)
      for (let i = 0; i < raw.length; i += 1) bytes[i] = raw.charCodeAt(i)
      return new TextDecoder().decode(bytes)
    }
    if (typeof Buffer !== 'undefined') {
      return Buffer.from(clean, 'base64').toString('utf8')
    }
    return null
  } catch {
    return null
  }
}

/**
 * Returns true if an SVG document string contains scripts, event handlers,
 * foreignObject, SMIL animation/discard attacks, XML DTD/entity/stylesheet
 * directives, malformed XML, unsafe URL schemes, or external references.
 */
export function hasDangerousSvgContent(svgText: string): boolean {
  const decoded = decodeBasicEntities(svgText)
  // Reject DTDs, entity declarations, and xml-stylesheet processing instructions.
  if (
    /<!\s*(?:doctype|entity)\b/i.test(svgText) ||
    /<!\s*(?:doctype|entity)\b/i.test(decoded) ||
    /<\?\s*xml-stylesheet\b/i.test(svgText) ||
    /<\?\s*xml-stylesheet\b/i.test(decoded)
  ) {
    return true
  }
  const dangerousTagPattern =
    /<\s*(?:[a-z0-9_-]+:)?(?:script|foreignobject|iframe|object|embed|animate(?:transform|motion|color)?|set|handler|discard|mpath)\b/i
  if (dangerousTagPattern.test(svgText) || dangerousTagPattern.test(decoded)) {
    return true
  }
  if (/\bon[a-z]+\s*=/i.test(svgText) || /\bon[a-z]+\s*=/i.test(decoded)) {
    return true
  }
  // Strip ASCII whitespace/control chars before scheme inspection
  const compactDecoded = decoded.replace(/[\u0000-\u0020\u007f]+/g, '').toLowerCase()
  if (
    compactDecoded.includes('javascript:') ||
    compactDecoded.includes('vbscript:') ||
    compactDecoded.includes('data:text/html') ||
    compactDecoded.includes('data:image/svg+xml')
  ) {
    return true
  }
  // Reject any href attribute (with any XML namespace prefix) not starting with '#'
  const hrefPattern =
    /\b(?:[a-z0-9_-]+:)?href\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/gi
  for (const text of [svgText, decoded]) {
    let match = hrefPattern.exec(text)
    while (match) {
      const value = (match[1] ?? match[2] ?? match[3] ?? '').trim()
      if (value && !value.startsWith('#')) return true
      match = hrefPattern.exec(text)
    }
    hrefPattern.lastIndex = 0
  }
  // Normalize CSS comments & backslash escapes before checking url(...) or @import
  const normalizedCss = normalizeCssForSecurityCheck(svgText)
  if (/(?:url\s*\(\s*['"]?(?!#)|@import)/i.test(normalizedCss)) {
    return true
  }
  // In DOM environments, also verify XML well-formedness & inspect parsed tree
  if (
    typeof DOMParser !== 'undefined' &&
    (svgText.trimStart().startsWith('<') ||
      /<\s*(?:[a-z0-9_-]+:)?svg\b/i.test(svgText))
  ) {
    const doc = new DOMParser().parseFromString(svgText, 'image/svg+xml')
    if (
      doc.documentElement?.localName.toLowerCase() !== 'svg' ||
      doc.querySelector('parsererror')
    ) {
      return true
    }
    for (const node of Array.from(doc.querySelectorAll('*'))) {
      const local = node.localName.toLowerCase()
      if (
        STRIP_SVG_ELEMENTS.has(local) &&
        local !== 'title' &&
        local !== 'desc' &&
        local !== 'style'
      ) {
        return true
      }
      for (const attr of Array.from(node.attributes)) {
        const attrLocal = attr.localName.toLowerCase()
        const attrName = attr.name.toLowerCase()
        if (attrLocal.startsWith('on') || attrName.startsWith('on')) return true
        if (attrLocal === 'href' && attr.value.trim() && !attr.value.trim().startsWith('#')) {
          return true
        }
        const attrCss = normalizeCssForSecurityCheck(attr.value)
        if (/(?:url\s*\(\s*['"]?(?!#)|@import)/i.test(attrCss)) return true
      }
      if (local === 'style') {
        const styleCss = normalizeCssForSecurityCheck(node.textContent ?? '')
        if (/(?:url\s*\(\s*['"]?(?!#)|@import)/i.test(styleCss)) return true
      }
    }
  }
  return false
}

export type UrlContext = 'href' | 'src' | 'img-src' | 'gallery-src'

/** Strict URL validation blocking obfuscated dangerous schemes. */
export function isSafeUrl(
  url: string,
  context: UrlContext = 'href',
  allowPreparedFsUrls = false,
): boolean {
  const trimmed = url.trim()
  if (!trimmed) return false
  const normalized = normalizeForSchemeCheck(trimmed)
  if (!normalized) return false

  // Always reject explicitly dangerous schemes.
  if (
    normalized.startsWith('javascript:') ||
    normalized.startsWith('vbscript:') ||
    normalized.startsWith('file:') ||
    normalized.startsWith('data:text/html') ||
    normalized.startsWith('data:image/svg+xml') ||
    normalized.startsWith('data:application/')
  ) {
    return false
  }

  if (context === 'gallery-src') {
    if (trimmed.includes('\\') || /%5c/i.test(trimmed)) return false
    if (normalized.startsWith('//')) return false
    if (normalized.startsWith('purescience-fs://')) return false
    if (normalized.startsWith('http://') || normalized.startsWith('https://')) {
      return true
    }
    if (SAFE_RASTER_DATA_IMAGE.test(trimmed)) return true
    if (/^[a-z][a-z0-9+.-]*:/i.test(normalized)) return false
    return isSafeEncodedRelativePath(trimmed)
  }

  if (context === 'img-src') {
    if (normalized.startsWith('purescience-fs://')) {
      return allowPreparedFsUrls
    }
    if (normalized.startsWith('http://') || normalized.startsWith('https://')) {
      return true
    }
    if (SAFE_RASTER_DATA_IMAGE.test(trimmed)) return true
    if (normalized.startsWith('data:') || normalized.startsWith('blob:')) {
      return false
    }
    if (/^[a-z][a-z0-9+.-]*:/i.test(normalized)) return false
    if (normalized.startsWith('//')) return false
    return true
  }

  if (context === 'src') {
    if (normalized.startsWith('purescience-fs://')) {
      return false
    }
    if (normalized.startsWith('http://') || normalized.startsWith('https://')) {
      return true
    }
    if (SAFE_RASTER_DATA_IMAGE.test(trimmed)) return true
    if (/^[a-z][a-z0-9+.-]*:/i.test(normalized)) return false
    if (normalized.startsWith('//')) return false
    return true
  }

  // context === 'href'
  if (normalized.startsWith('#')) return true
  if (
    normalized.startsWith('http://') ||
    normalized.startsWith('https://') ||
    normalized.startsWith('mailto:') ||
    normalized.startsWith('tel:')
  ) {
    return true
  }
  if (normalized.startsWith('data:') || normalized.startsWith('blob:')) {
    return false
  }
  if (/^[a-z][a-z0-9+.-]*:/i.test(normalized)) return false
  if (normalized.startsWith('//')) return false
  return true
}

/**
 * Validate an already-decoded literal relative filesystem path.
 * Does NOT call `decodeURIComponent`, so filenames containing literal `%`
 * (e.g. `assets/100%_chart.png`) are preserved cleanly.
 */
function isSafeLiteralRelativePath(path: string): boolean {
  if (!path || /[\u0000-\u001f\u007f]/.test(path)) return false
  if (path.includes('\\') || path.includes('?') || path.includes('#')) return false
  if (path.startsWith('/') || /^[a-zA-Z]:/.test(path)) return false
  const segments = path.split('/')
  return segments.every(segment => segment !== '' && segment !== '..' && segment !== '.')
}

/**
 * Decode valid `%XX` URL percent escapes iteratively until stable (up to 4
 * passes) without failing on literal non-hex `%` characters like `100%_chart.png`.
 */
function decodeUrlEscapesIteratively(input: string): string {
  let current = input
  for (let pass = 0; pass < 4; pass += 1) {
    const next = current.replace(/(?:%[0-9a-fA-F]{2})+/g, encoded => {
      try {
        return decodeURIComponent(encoded)
      } catch {
        return encoded
      }
    })
    if (next === current) break
    current = next
  }
  return current
}

/** Validate a relative path that may come from Markdown/URL syntax. */
function isSafeEncodedRelativePath(path: string): boolean {
  if (!isSafeLiteralRelativePath(path)) return false
  const decoded = decodeUrlEscapesIteratively(path)
  return isSafeLiteralRelativePath(decoded)
}

/**
 * Resolve a candidate image/asset `src` to a safe package-relative path.
 * Rejects `..`, double-encoded traversal, `?`/`#`, control characters (before
 * or after decoding), absolute paths, backslashes, and `file://` URLs outside
 * `packagePath`. Preserves legitimate literal `%` filenames like `100%_chart.png`.
 */
export function resolveSafePackageRelativeAssetPath(
  src: string,
  packagePath: string,
): string | null {
  const trimmed = src.trim()
  const root = packagePath.replace(/\/+$/, '')
  if (!trimmed || !root) return null
  if (/[\u0000-\u001f\u007f]/.test(trimmed)) return null
  if (trimmed.includes('\\') || /%5c/i.test(trimmed)) return null

  const normalizedScheme = normalizeForSchemeCheck(trimmed)
  if (normalizedScheme.startsWith('file://')) {
    try {
      const url = new URL(trimmed)
      if (url.hostname && url.hostname !== 'localhost') return null
      if (url.search || url.hash) return null
      const pathname = decodeUrlEscapesIteratively(url.pathname)
      if (/[\u0000-\u001f\u007f]/.test(pathname) || pathname.includes('\\')) return null
      if (!pathname.startsWith(`${root}/`)) return null
      const relative = pathname.slice(root.length + 1)
      return isSafeLiteralRelativePath(relative) ? relative : null
    } catch {
      return null
    }
  }

  // Reject any other scheme (http:, https:, purescience-fs:, javascript:, data:, etc.)
  if (/^[a-z][a-z0-9+.-]*:/i.test(normalizedScheme)) return null
  // Reject protocol-relative and absolute paths
  if (trimmed.startsWith('/')) return null

  return isSafeEncodedRelativePath(trimmed) ? trimmed : null
}

/**
 * Verify an already-decoded absolute filesystem path lies strictly inside
 * `packagePath` with no traversal, backslashes, query/fragment, or control chars.
 */
export function isAbsolutePathInsidePackage(
  absolutePath: string,
  packagePath: string,
): boolean {
  const root = packagePath.replace(/\/+$/, '')
  if (!root || !absolutePath || absolutePath.includes('\\')) return false
  if (!absolutePath.startsWith(`${root}/`)) return false
  const relative = absolutePath.slice(root.length + 1)
  return isSafeLiteralRelativePath(relative)
}

function isSafeStyleValue(value: string): boolean {
  const normalized = normalizeCssForSecurityCheck(value)
  if (
    /(?:expression\s*\(|javascript\s*:|vbscript\s*:|behavior\s*:|-moz-binding|@import|url\s*\()/i.test(
      normalized,
    )
  ) {
    return false
  }
  return true
}

function sanitizeVideoIframeAllow(value: string): string {
  return value
    .split(';')
    .map(part => part.trim().toLowerCase())
    .filter(part => ALLOWED_VIDEO_IFRAME_PERMISSIONS.has(part))
    .join('; ')
}

function isTrustedVideoIframe(element: Element): boolean {
  if (element.localName.toLowerCase() !== 'iframe') return false
  const src = element.getAttribute('src')?.trim() ?? ''
  if (!TRUSTED_VIDEO_IFRAME_SRC.test(src)) return false
  const parent = element.parentElement
  if (!parent || parent.localName.toLowerCase() !== 'figure') return false
  const source = parent.getAttribute('data-video-source')?.trim() ?? ''
  return TRUSTED_VIDEO_SOURCE_URL.test(source)
}

function hasVerifiedWriterAssetSrc(element: Element): boolean {
  const assetSrc = element.getAttribute('data-writer-asset-src')?.trim() ?? ''
  return Boolean(assetSrc && isSafeLiteralRelativePath(assetSrc))
}

function isSafeLocalAssetSvgImg(element: Element, src: string): boolean {
  if (element.localName.toLowerCase() !== 'img') return false
  if (!hasVerifiedWriterAssetSrc(element)) return false
  const match = SAFE_SVG_DATA_IMAGE.exec(src.trim())
  if (!match) return false
  const svgText = decodeBase64Utf8(match[1]!)
  if (svgText === null) return false
  return !hasDangerousSvgContent(svgText)
}

function sanitizeDomTree(root: Element, options: SanitizeHtmlOptions): void {
  const walk = (parent: Element, inSvg: boolean): void => {
    const children = Array.from(parent.children)
    for (const element of children) {
      const tag = element.localName.toLowerCase()
      const nextInSvg = inSvg || tag === 'svg'

      if (
        options.allowTrustedVideoIframes &&
        tag === 'iframe' &&
        isTrustedVideoIframe(element)
      ) {
        for (const attr of Array.from(element.attributes)) {
          const attrName = attr.name.toLowerCase()
          if (!ALLOWED_VIDEO_IFRAME_ATTRS.has(attrName)) {
            element.removeAttribute(attr.name)
          } else if (attrName === 'style' && !isSafeStyleValue(attr.value)) {
            element.removeAttribute(attr.name)
          } else if (attrName === 'allow') {
            const safeAllow = sanitizeVideoIframeAllow(attr.value)
            if (safeAllow) element.setAttribute('allow', safeAllow)
            else element.removeAttribute(attr.name)
          }
        }
        element.innerHTML = ''
        continue
      }

      if (STRIP_ELEMENTS.has(tag) || (nextInSvg && STRIP_SVG_ELEMENTS.has(tag))) {
        element.remove()
        continue
      }

      for (const attr of Array.from(element.attributes)) {
        const name = attr.name.toLowerCase()
        const localName = attr.localName.toLowerCase()
        const value = attr.value

        if (name.startsWith('on') || localName.startsWith('on') || name === 'srcdoc') {
          element.removeAttribute(attr.name)
          continue
        }

        if (name === 'style') {
          if (!isSafeStyleValue(value)) {
            element.removeAttribute(attr.name)
          }
          continue
        }

        if (name === 'srcset') {
          const safeEntries = value
            .split(',')
            .map(part => part.trim())
            .filter(Boolean)
            .filter(part => {
              const candidate = part.split(/\s+/)[0] ?? ''
              return isSafeUrl(candidate, 'img-src', false)
            })
          if (safeEntries.length) {
            element.setAttribute('srcset', safeEntries.join(', '))
          } else {
            element.removeAttribute(attr.name)
          }
          continue
        }

        if (URL_ATTRS.has(name) || localName === 'href') {
          if (nextInSvg && (name === 'href' || localName === 'href')) {
            if (!value.trim().startsWith('#')) {
              element.removeAttribute(attr.name)
            }
            continue
          }

          if (
            tag === 'img' &&
            name === 'src' &&
            options.allowLocalAssetSvgImg &&
            isSafeLocalAssetSvgImg(element, value)
          ) {
            continue
          }

          const allowFs =
            tag === 'img' &&
            name === 'src' &&
            options.allowPreparedFsUrls === true &&
            hasVerifiedWriterAssetSrc(element)

          const urlContext: UrlContext =
            name === 'href' || localName === 'href'
              ? 'href'
              : tag === 'img' && name === 'src'
                ? 'img-src'
                : 'src'
          if (!isSafeUrl(value, urlContext, allowFs)) {
            element.removeAttribute(attr.name)
          }
        }
      }

      walk(element, nextInSvg)
    }
  }

  walk(root, false)
}

interface ParsedAttr {
  name: string
  value: string
  hasValue: boolean
}

function parseAttributesQuoteAware(raw: string): ParsedAttr[] {
  const attrs: ParsedAttr[] = []
  let i = 0
  const len = raw.length
  while (i < len) {
    // Skip whitespace and stray '/' separators (e.g. <img/src=x/onerror=1>)
    while (i < len && /[\s/]/.test(raw[i]!)) i += 1
    if (i >= len) break
    const nameStart = i
    while (i < len && !/[\s=/>"'`<]/.test(raw[i]!)) i += 1
    const name = raw.slice(nameStart, i)
    if (!name || !/^[a-zA-Z_:][a-zA-Z0-9_.:-]*$/.test(name)) {
      i += 1
      continue
    }
    while (i < len && /\s/.test(raw[i]!)) i += 1
    if (i < len && raw[i] === '=') {
      i += 1
      while (i < len && /\s/.test(raw[i]!)) i += 1
      let value = ''
      if (i < len && (raw[i] === '"' || raw[i] === "'")) {
        const quote = raw[i]!
        i += 1
        const valStart = i
        while (i < len && raw[i] !== quote) i += 1
        value = raw.slice(valStart, i)
        if (i < len && raw[i] === quote) i += 1
      } else {
        const valStart = i
        while (i < len && !/[\s/>]/.test(raw[i]!)) i += 1
        value = raw.slice(valStart, i)
      }
      attrs.push({ name, value, hasValue: true })
    } else {
      attrs.push({ name, value: '', hasValue: false })
    }
  }
  return attrs
}

function findTagEndQuoteAware(
  input: string,
  startIndex: number,
): { gt: number; innerLt: number } {
  let quote: '"' | "'" | null = null
  for (let i = startIndex + 1; i < input.length; i += 1) {
    const ch = input[i]!
    if (quote) {
      if (ch === quote) quote = null
    } else if (ch === '"' || ch === "'") {
      quote = ch
    } else if (ch === '<') {
      return { gt: -1, innerLt: i }
    } else if (ch === '>') {
      return { gt: i, innerLt: -1 }
    }
  }
  return { gt: -1, innerLt: -1 }
}

function localTagName(rawTag: string): string {
  const lower = rawTag.toLowerCase()
  const colon = lower.lastIndexOf(':')
  return colon >= 0 ? lower.slice(colon + 1) : lower
}

function escapeAttrValue(value: string): string {
  return value.replace(/"/g, '&quot;')
}

/**
 * Strict quote-aware tokenizer fallback for non-DOM environments (Node/SSR).
 * Runs in a fixed-point loop to defeat nested-tag smuggling (`<scr<script>ipt>`).
 */
function sanitizeHtmlFallbackOnce(
  html: string,
  options: SanitizeHtmlOptions,
): string {
  let out = ''
  let i = 0
  let svgDepth = 0
  let videoFigureDepth = 0
  let skipUntilCloseTag: string | null = null
  let skipDepth = 0

  while (i < html.length) {
    const lt = html.indexOf('<', i)
    if (lt === -1) {
      if (!skipUntilCloseTag) out += html.slice(i)
      break
    }
    if (!skipUntilCloseTag && lt > i) {
      out += html.slice(i, lt)
    }

    // HTML comments / doctype / processing instructions: strip entirely
    if (html.startsWith('<!--', lt)) {
      const endComment = html.indexOf('-->', lt + 4)
      i = endComment === -1 ? html.length : endComment + 3
      continue
    }
    if (html.startsWith('<!', lt) || html.startsWith('<?', lt)) {
      const gt = html.indexOf('>', lt + 2)
      i = gt === -1 ? html.length : gt + 1
      continue
    }

    const { gt, innerLt } = findTagEndQuoteAware(html, lt)
    if (innerLt !== -1) {
      // Unquoted '<' before '>': escape this malformed opener as text and resume at innerLt
      if (!skipUntilCloseTag) {
        out += `&lt;${html.slice(lt + 1, innerLt)}`
      }
      i = innerLt
      continue
    }
    if (gt === -1) {
      // Unclosed tag fragment — drop it safely
      break
    }

    const inside = html.slice(lt + 1, gt)
    const isClosing = /^\s*\//.test(inside)
    const nameMatch = isClosing
      ? /^\s*\/\s*([a-zA-Z][a-zA-Z0-9:-]*)/.exec(inside)
      : /^\s*([a-zA-Z][a-zA-Z0-9:-]*)/.exec(inside)

    if (!nameMatch) {
      if (!skipUntilCloseTag) out += '&lt;'
      i = lt + 1
      continue
    }

    const rawTag = nameMatch[1]!
    const tag = localTagName(rawTag)
    const selfClosing = !isClosing && /\/\s*$/.test(inside)
    const rawAttrs = isClosing
      ? ''
      : inside.slice(nameMatch[0].length).replace(/\/\s*$/, '')

    if (skipUntilCloseTag) {
      if (tag === skipUntilCloseTag) {
        if (isClosing) {
          skipDepth -= 1
          if (skipDepth <= 0) skipUntilCloseTag = null
        } else if (!selfClosing) {
          skipDepth += 1
        }
      }
      i = gt + 1
      continue
    }

    if (isClosing) {
      if (tag === 'svg' && svgDepth > 0) svgDepth -= 1
      if (tag === 'figure' && videoFigureDepth > 0) videoFigureDepth -= 1
      if (STRIP_ELEMENTS.has(tag) || (svgDepth > 0 && STRIP_SVG_ELEMENTS.has(tag))) {
        i = gt + 1
        continue
      }
      out += `</${rawTag}>`
      i = gt + 1
      continue
    }

    const attrs = parseAttributesQuoteAware(rawAttrs)

    // Special case: trusted video iframe inside verified <figure data-video-source="...">
    if (tag === 'iframe') {
      const srcAttr = attrs.find(a => a.name.toLowerCase() === 'src')?.value.trim() ?? ''
      if (
        options.allowTrustedVideoIframes &&
        videoFigureDepth > 0 &&
        TRUSTED_VIDEO_IFRAME_SRC.test(srcAttr) &&
        !selfClosing
      ) {
        // Must have a matching closing </iframe> to avoid unclosed iframe smuggling
        const closeMatch = new RegExp('<\\s*\\/\\s*iframe\\s*>', 'i').exec(html.slice(gt + 1))
        if (closeMatch) {
          const keptIframeAttrs: string[] = []
          for (const attr of attrs) {
            const name = attr.name.toLowerCase()
            if (!ALLOWED_VIDEO_IFRAME_ATTRS.has(name)) continue
            if (name === 'style' && !isSafeStyleValue(attr.value)) continue
            if (name === 'allow') {
              const safeAllow = sanitizeVideoIframeAllow(attr.value)
              if (safeAllow) keptIframeAttrs.push(`allow="${escapeAttrValue(safeAllow)}"`)
              continue
            }
            keptIframeAttrs.push(
              attr.hasValue
                ? `${name}="${escapeAttrValue(attr.value)}"`
                : name,
            )
          }
          out += `<iframe${keptIframeAttrs.length ? ` ${keptIframeAttrs.join(' ')}` : ''}></iframe>`
          i = gt + 1 + closeMatch.index + closeMatch[0].length
          continue
        }
      }
      // Untrusted or unclosed iframe: strip tag and any body up to closing tag
      if (!selfClosing) {
        skipUntilCloseTag = 'iframe'
        skipDepth = 1
      }
      i = gt + 1
      continue
    }

    const inSvg = svgDepth > 0 || tag === 'svg'
    if (STRIP_ELEMENTS.has(tag) || (inSvg && STRIP_SVG_ELEMENTS.has(tag))) {
      const isVoid =
        tag === 'meta' || tag === 'base' || tag === 'link' || tag === 'embed' || tag === 'frame'
      if (!selfClosing && !isVoid) {
        skipUntilCloseTag = tag
        skipDepth = 1
      }
      i = gt + 1
      continue
    }

    if (tag === 'svg' && !selfClosing) svgDepth += 1
    if (tag === 'figure' && !selfClosing) {
      const videoSource =
        attrs.find(a => a.name.toLowerCase() === 'data-video-source')?.value.trim() ?? ''
      if (TRUSTED_VIDEO_SOURCE_URL.test(videoSource)) videoFigureDepth += 1
    }

    const writerAssetSrc = attrs
      .find(a => a.name.toLowerCase() === 'data-writer-asset-src')
      ?.value.trim()
    const hasSafeWriterAsset = Boolean(
      writerAssetSrc && isSafeLiteralRelativePath(writerAssetSrc),
    )

    const keptAttrs: string[] = []
    for (const attr of attrs) {
      const name = attr.name.toLowerCase()
      const attrLocal = localTagName(name)
      if (name.startsWith('on') || attrLocal.startsWith('on') || name === 'srcdoc') {
        continue
      }
      if (name === 'style') {
        if (!isSafeStyleValue(attr.value)) continue
      } else if (name === 'srcset') {
        const safeEntries = attr.value
          .split(',')
          .map(part => part.trim())
          .filter(Boolean)
          .filter(part => {
            const candidate = part.split(/\s+/)[0] ?? ''
            return isSafeUrl(candidate, 'img-src', false)
          })
        if (safeEntries.length) {
          keptAttrs.push(`srcset="${escapeAttrValue(safeEntries.join(', '))}"`)
        }
        continue
      } else if (URL_ATTRS.has(name) || attrLocal === 'href') {
        if (inSvg && (name === 'href' || attrLocal === 'href')) {
          if (!attr.value.trim().startsWith('#')) continue
        } else if (
          tag === 'img' &&
          name === 'src' &&
          options.allowLocalAssetSvgImg &&
          hasSafeWriterAsset
        ) {
          const svgMatch = SAFE_SVG_DATA_IMAGE.exec(attr.value.trim())
          const decodedSvg = svgMatch ? decodeBase64Utf8(svgMatch[1]!) : null
          if (decodedSvg !== null && !hasDangerousSvgContent(decodedSvg)) {
            keptAttrs.push(`${attr.name}="${escapeAttrValue(attr.value)}"`)
            continue
          }
          const allowFs = options.allowPreparedFsUrls === true && hasSafeWriterAsset
          if (!isSafeUrl(attr.value, 'img-src', allowFs)) continue
        } else {
          const allowFs =
            tag === 'img' &&
            name === 'src' &&
            options.allowPreparedFsUrls === true &&
            hasSafeWriterAsset
          const urlContext: UrlContext =
            name === 'href' || attrLocal === 'href'
              ? 'href'
              : tag === 'img' && name === 'src'
                ? 'img-src'
                : 'src'
          if (!isSafeUrl(attr.value, urlContext, allowFs)) continue
        }
      }

      keptAttrs.push(
        attr.hasValue
          ? `${attr.name}="${escapeAttrValue(attr.value)}"`
          : attr.name,
      )
    }

    out += `<${rawTag}${keptAttrs.length ? ` ${keptAttrs.join(' ')}` : ''}${selfClosing ? ' /' : ''}>`
    i = gt + 1
  }

  return out
}

function sanitizeHtmlFallback(
  html: string,
  options: SanitizeHtmlOptions,
): string {
  let current = html
  for (let pass = 0; pass < 5; pass += 1) {
    const next = sanitizeHtmlFallbackOnce(current, options)
    if (next === current) break
    current = next
  }
  return current
}

/** Sanitize HTML before rendering via `dangerouslySetInnerHTML`. */
export function sanitizeHtml(
  html: string,
  options: SanitizeHtmlOptions = {},
): string {
  if (!html || !html.trim()) return html
  if (typeof DOMParser !== 'undefined') {
    const doc = new DOMParser().parseFromString(html, 'text/html')
    sanitizeDomTree(doc.body, options)
    return doc.body.innerHTML
  }
  return sanitizeHtmlFallback(html, options)
}

function escapeAttrAndText(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

/**
 * Replace `[[Target]]` and `[[Target|Display]]` wikilinks in rendered HTML by
 * walking DOM text nodes only — never mutating attributes, `<pre>`, `<code>`,
 * `<a>`, `<svg>`, `<math>`, `<textarea>`, `<script>`, or `<style>`, and never
 * double-escaping `&`, `'`, `"`, or corrupting surrounding entities like `&nbsp;`.
 */
export function renderWikiLinksInHtml(
  html: string,
  hasPage: (targetTitle: string) => boolean,
): string {
  if (!html || (!html.includes('[[') && !html.includes('\\[\\['))) return html
  if (typeof DOMParser === 'undefined') {
    return html.replace(
      /(<pre\b[\s\S]*?<\/pre>|<code\b[\s\S]*?<\/code>|<a\b[\s\S]*?<\/a>|<svg\b[\s\S]*?<\/svg>|<math\b[\s\S]*?<\/math>|<textarea\b[\s\S]*?<\/textarea>|<script\b[\s\S]*?<\/script>|<style\b[\s\S]*?<\/style>|<[^>]+>)|([^<]+)/gi,
      (whole, skipped: string | undefined, text: string | undefined) => {
        if (skipped || text === undefined) return whole
        if (!text.includes('[[') && !text.includes('\\[\\[')) return whole
        // Only rewrite matched wikilink spans; leave surrounding HTML entities untouched!
        return text.replace(
          /(?:\\\[\\\[|\[\[)([^\]]+?)(?:\\\]\\\]|\]\])/g,
          (match, rawInner: string) => {
            const decoded = decodeBasicEntities(rawInner)
            const pipeIdx = decoded.indexOf('|')
            const target = (pipeIdx === -1 ? decoded : decoded.slice(0, pipeIdx)).trim()
            const display =
              (pipeIdx === -1 ? target : decoded.slice(pipeIdx + 1).trim()) || target
            if (!target) return match
            const exists = hasPage(target)
            return `<a href="#" data-wiki-title="${escapeAttrAndText(target)}"${
              exists ? '' : ' class="is-missing"'
            }>${escapeAttrAndText(display)}</a>`
          },
        )
      },
    )
  }

  const doc = new DOMParser().parseFromString(html, 'text/html')
  const textNodes: Text[] = []
  const collectTextNodes = (node: Node): void => {
    for (const child of Array.from(node.childNodes)) {
      if (child.nodeType === 3) {
        textNodes.push(child as Text)
      } else if (child.nodeType === 1) {
        const tag = (child as Element).localName.toLowerCase()
        if (
          tag === 'pre' ||
          tag === 'code' ||
          tag === 'a' ||
          tag === 'svg' ||
          tag === 'math' ||
          tag === 'script' ||
          tag === 'style' ||
          tag === 'textarea'
        ) {
          continue
        }
        collectTextNodes(child)
      }
    }
  }
  collectTextNodes(doc.body)

  let changed = false
  for (const node of textNodes) {
    const rawValue = node.nodeValue ?? ''
    const normalized = normalizeWikiLinkEscapes(rawValue)
    if (!normalized.includes('[[')) continue
    const pattern = /\[\[([^\]]+)\]\]/g
    let match = pattern.exec(normalized)
    if (!match) continue

    const fragment = doc.createDocumentFragment()
    let lastIndex = 0
    while (match) {
      if (match.index > lastIndex) {
        fragment.appendChild(
          doc.createTextNode(normalized.slice(lastIndex, match.index)),
        )
      }
      const inner = match[1] ?? ''
      const pipeIdx = inner.indexOf('|')
      const target = (pipeIdx === -1 ? inner : inner.slice(0, pipeIdx)).trim()
      const display =
        (pipeIdx === -1 ? target : inner.slice(pipeIdx + 1).trim()) || target
      if (!target) {
        fragment.appendChild(doc.createTextNode(match[0]))
      } else {
        const anchor = doc.createElement('a')
        anchor.setAttribute('href', '#')
        anchor.setAttribute('data-wiki-title', target)
        if (!hasPage(target)) anchor.setAttribute('class', 'is-missing')
        anchor.textContent = display
        fragment.appendChild(anchor)
      }
      lastIndex = match.index + match[0].length
      match = pattern.exec(normalized)
    }
    if (lastIndex < normalized.length) {
      fragment.appendChild(doc.createTextNode(normalized.slice(lastIndex)))
    }
    node.parentNode?.replaceChild(fragment, node)
    changed = true
  }

  return changed ? doc.body.innerHTML : html
}

/**
 * Add deterministic `id` attributes to headings in reading HTML and return both
 * the anchored HTML and the aligned outline headings (exact `id`, clean text,
 * and level) so TOC entries always match rendered DOM headings.
 */
export function addHeadingAnchorsToHtml(html: string): {
  html: string
  headings: RenderedHeading[]
} {
  if (!html.trim() || typeof DOMParser === 'undefined') {
    return { html, headings: [] }
  }
  const doc = new DOMParser().parseFromString(html, 'text/html')
  const nodes = Array.from(doc.body.querySelectorAll('h1, h2, h3, h4, h5, h6'))
  if (!nodes.length) return { html, headings: [] }
  const seen = new Map<string, number>()
  const headings: RenderedHeading[] = []
  for (const heading of nodes) {
    const text = heading.textContent?.trim() ?? ''
    if (!text) continue
    const base =
      text
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '') || 'section'
    const count = seen.get(base) ?? 0
    seen.set(base, count + 1)
    const id = count === 0 ? `heading-${base}` : `heading-${base}-${count}`
    heading.setAttribute('id', id)
    headings.push({
      id,
      text,
      level: Number.parseInt(heading.tagName.slice(1), 10) || 1,
    })
  }
  return { html: doc.body.innerHTML, headings }
}
